export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/** Drops every document for one organization. Other organizations stay put. */
export async function deleteSearchDocumentsForOrg(orgId: OrgId): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .run();
}

/**
 * A project is searchable while it is live. An issue is searchable while it
 * and its project are live. A comment is searchable while it, its issue and
 * that issue's project are all live. Applied at read time so a stale document
 * cannot change the hits or the reported total.
 */
function searchablePredicate(): SQL {
  const db = getDb();

  const liveProject = exists(
    db
      .select({ id: projects.id })
      .from(projects)
      .where(
        and(
          eq(projects.id, searchIndex.subjectId),
          eq(projects.orgId, searchIndex.orgId),
          isNull(projects.archivedAt),
        ),
      ),
  );

  const liveIssue = exists(
    db
      .select({ id: issues.id })
      .from(issues)
      .innerJoin(
        projects,
        and(eq(projects.id, issues.projectId), eq(projects.orgId, issues.orgId)),
      )
      .where(
        and(
          eq(issues.id, searchIndex.subjectId),
          eq(issues.orgId, searchIndex.orgId),
          isNull(issues.archivedAt),
          isNull(projects.archivedAt),
        ),
      ),
  );

  const liveComment = exists(
    db
      .select({ id: comments.id })
      .from(comments)
      .innerJoin(
        issues,
        and(eq(issues.id, comments.issueId), eq(issues.orgId, comments.orgId)),
      )
      .innerJoin(
        projects,
        and(eq(projects.id, issues.projectId), eq(projects.orgId, issues.orgId)),
      )
      .where(
        and(
          eq(comments.id, searchIndex.subjectId),
          eq(comments.orgId, searchIndex.orgId),
          isNull(comments.archivedAt),
          isNull(issues.archivedAt),
          isNull(projects.archivedAt),
        ),
      ),
  );

  return or(
    and(eq(searchIndex.subjectKind, "project"), liveProject),
    and(eq(searchIndex.subjectKind, "issue"), liveIssue),
    and(eq(searchIndex.subjectKind, "comment"), liveComment),
  )!;
}

