import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function hits(tenant: Tenant, q: string, kinds: Array<"issue" | "comment" | "project"> = ["issue", "comment", "project"]) {
  const page = await searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds,
    limit: 100,
    cursor: null,
  });
  return { total: page.total, ids: page.items.map((item) => item.id) };
}

describe("search archive visibility", () => {
  it("hides an archived issue and its comments, and keeps later edits hidden", async () => {
    const tenant = await createTenant("archissue", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchiveMeIssue" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ArchiveMeComment",
      parentId: null,
      mentionedUserIds: [],
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    expect(await hits(tenant, "ArchiveMeIssue")).toMatchObject({ total: 0, ids: [] });
    expect(await hits(tenant, "ArchiveMeComment")).toMatchObject({ total: 0, ids: [] });

    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "ArchiveMeCommentEdited",
    });
    expect(await hits(tenant, "ArchiveMeCommentEdited")).toMatchObject({ total: 0 });
    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(1);
  });

  it("hides a project and its kept issues, then restores only what stayed live", async () => {
    const tenant = await createTenant("archproj", "growth");
    const kept = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "KeptIssueMarker" }),
    );
    const doomed = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "DoomedIssueMarker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      body: "KeptCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doomed.id,
      body: "DoomedCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, doomed.id);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    expect(await hits(tenant, "platform")).toMatchObject({ total: 0 });
    expect(await hits(tenant, "KeptIssueMarker")).toMatchObject({ total: 0 });
    expect(await hits(tenant, "KeptCommentMarker")).toMatchObject({ total: 0 });
    expect(await hits(tenant, "DoomedIssueMarker")).toMatchObject({ total: 0 });

    const late = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      body: "LateCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      title: "KeptIssueEdited",
    });
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: late.id,
      body: "LateCommentEdited",
    });

    expect(await hits(tenant, "LateComment")).toMatchObject({ total: 0 });
    expect(await hits(tenant, "KeptIssueEdited")).toMatchObject({ total: 0 });
    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(0);

