    expect(indexed).toBe(1 + 120 + 120);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherCountBefore);

    const first = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "NeedleLive",
      kinds: ["issue"],
      limit: 100,
      cursor: null,
    });
    expect(first.total).toBe(120);
    expect(first.items).toHaveLength(100);
    expect(first.nextCursor).not.toBeNull();

    const second = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "NeedleLive",
      kinds: ["issue"],
      limit: 100,
      cursor: first.nextCursor,
    });
    expect(second.items.length + first.items.length).toBe(120);

    const comments = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "NeedleComment",
      kinds: ["comment"],
      limit: 100,
      cursor: null,
    });
    expect(comments.total).toBe(120);

    expect((await hits(tenant, "NeedleArchived")).total).toBe(0);
    expect((await hits(tenant, "NeedleDeleted")).total).toBe(0);
    expect((await hits(tenant, "NeedleArchivedProject")).total).toBe(0);
    expect((await hits(tenant, "NeedleHidden")).total).toBe(0);
    expect((await hits(tenant, "NeedleOrphan")).total).toBe(0);
    expect((await hits(other, "OtherOrgMarker", ["issue"])).total).toBe(1);
  });
});
